INSERT INTO `products` VALUES (43,19,15,'Smart 1 Gang Switch- STATA','STATA Smart 1 Gang Switch','ST-SGS1','39','switch','Regular','Black,White','2199',NULL,'2200','STATA Smart App,Smart Switch,Touch Switch, Scheduling,Remotely Controllable','𝐓𝐫𝐚𝐧𝐬𝐟𝐨𝐫𝐦 𝐘𝐨𝐮𝐫 𝐇𝐨𝐦𝐞 𝐰𝐢𝐭𝐡 𝐭𝐡𝐞 𝟏 𝐆𝐚𝐧𝐠 𝐒𝐦𝐚𝐫𝐭 𝐒𝐰𝐢𝐭𝐜𝐡 (𝐖𝐢-𝐅𝐢): 𝐓𝐡𝐞 𝐄𝐩𝐢𝐭𝐨𝐦𝐞 𝐨𝐟 𝐂𝐨𝐧𝐯𝐞𝐧𝐢𝐞𝐧𝐜𝐞 𝐚𝐧𝐝 𝐄𝐟𝐟𝐢𝐜𝐢𝐞𝐧𝐜𝐲\r\nIn the age of smart technology, turning your home into a modern haven is easier than ever. Introducing our 1 Gang Smart Switch (Wi-Fi) enable, a game-changing device that brings ultimate control and convenience to your fingertips. Say goodbye to traditional switches and embrace the future of smart living.\r\n\r\n𝐊𝐞𝐲 𝐅𝐞𝐚𝐭𝐮𝐫𝐞𝐬:\r\n𝐒𝐞𝐚𝐦𝐥𝐞𝐬𝐬 𝐂𝐨𝐧𝐧𝐞𝐜𝐭𝐢𝐯𝐢𝐭𝐲: The 1 Gang Smart Switch seamlessly connects to your home\'s Wi-Fi network, allowing you to control your lights from anywhere using your smartphone or voice commands.\r\n\r\n𝐄𝐚𝐬𝐲 𝐈𝐧𝐬𝐭𝐚𝐥𝐥𝐚𝐭𝐢𝐨𝐧: With a simple and straightforward installation process, you can replace your existing switch with the smart switch without the need for extensive rewiring.\r\n\r\n𝐑𝐞𝐦𝐨𝐭𝐞 𝐀𝐜𝐜𝐞𝐬𝐬: Forgot to turn off the lights before leaving home? No worries! With the smart switch, you can remotely control your lights, ensuring energy efficiency and peace of mind.\r\n\r\n𝐕𝐨𝐢𝐜𝐞 𝐂𝐨𝐧𝐭𝐫𝐨𝐥: Compatible with popular voice assistants like Amazon Alexa and Google Assistant, the smart switch lets you control your lights with just your voice.\r\n\r\n𝐂𝐮𝐬𝐭𝐨𝐦𝐢𝐳𝐚𝐛𝐥𝐞 𝐒𝐜𝐡𝐞𝐝𝐮𝐥𝐢𝐧𝐠: Create personalized schedules for your lights to turn on and off at specific times, adding an extra layer of security and energy savings.\r\n\r\n𝐃𝐢𝐦𝐦𝐢𝐧𝐠 𝐅𝐮𝐧𝐜𝐭𝐢𝐨𝐧𝐚𝐥𝐢𝐭𝐲: Enjoy the flexibility of adjusting the brightness of your lights with the dimming feature, setting the perfect ambiance for any occasion.\r\n\r\n𝐄𝐧𝐞𝐫𝐠𝐲 𝐄𝐟𝐟𝐢𝐜𝐢𝐞𝐧𝐜𝐲: The smart switch promotes energy efficiency by allowing you to monitor and manage your lighting usage effectively.\r\n\r\n𝐒𝐭𝐲𝐥𝐢𝐬𝐡 𝐚𝐧𝐝 𝐃𝐮𝐫𝐚𝐛𝐥𝐞: Crafted with premium materials, the 1 Gang Smart Switch boasts a sleek design that complements any interior décor while ensuring long-lasting performance.\r\n\r\n𝐂𝐨𝐦𝐩𝐚𝐭𝐢𝐛𝐢𝐥𝐢𝐭𝐲: The smart switch works with most standard bulb types, making it a versatile addition to your home automation setup.\r\n\r\n𝐒𝐦𝐚𝐫𝐭 𝐇𝐨𝐦𝐞 𝐈𝐧𝐭𝐞𝐠𝐫𝐚𝐭𝐢𝐨𝐧: Integrate the 1 Gang Smart Switch into your existing smart home ecosystem, creating a connected and intelligent living space.\r\n\r\nWith the 1 Gang Smart Switch (Wi-Fi) enable, you can effortlessly control your lights, set the perfect ambiance, and save energy with just a few taps on your smartphone or simple voice commands. Experience the convenience and efficiency of a smart home by incorporating the smart switch into your daily life.\r\n\r\n\r\nUpgrade your home with the 1 Gang Smart Switch (Wi-Fi) enable and embrace the future of smart living. Experience the convenience of controlling your lights from anywhere and enjoy the benefits of energy efficiency and customization. Simplify your life with this versatile and user-friendly smart switch, now available at an affordable price in Bangladesh. Take the first step towards a smarter home and elevate your living experience with the 1 Gang Smart Switch. Experience the convenience, energy savings, and modernity it brings to your living space. Invest in the future of home automation today and transform your house into a truly intelligent home.\r\n\r\n\r\n•𝐏𝐚𝐧𝐞𝐥: Crystal glass panel, no fading. Elegant and stylish \r\nIntegrated panel design\r\n•𝐒𝐜𝐡𝐞𝐝𝐮𝐥𝐞𝐝: you can set timer for these smart devices. \r\n•𝐖𝐚𝐭𝐞𝐫𝐩𝐫𝐨𝐨𝐟: Yes\r\n•𝐀𝐧𝐭𝐢-𝐜𝐫𝐞𝐞𝐩𝐢𝐧𝐠: Yes\r\n•𝐒𝐰𝐢𝐭𝐜𝐡 𝐓𝐲𝐩𝐞: Touch\r\n•𝐕𝐨𝐥𝐭𝐚𝐠𝐞: 170V-240V \r\n•𝐋𝐨𝐚𝐝 𝐏𝐨𝐰𝐞𝐫: 5-300W/Gang \r\n•𝐂𝐞𝐫𝐭𝐢𝐟𝐢𝐜𝐚𝐭𝐢𝐨𝐧: CE, FCC, RoHS\r\n•𝐖𝐨𝐫𝐤𝐢𝐧𝐠 𝐓𝐞𝐦𝐩𝐞𝐫𝐚𝐭𝐮𝐫𝐞: -20-70 Degree\r\n\r\n𝐒𝐞𝐫𝐯𝐢𝐜𝐞 & 𝐖𝐚𝐫𝐫𝐚𝐧𝐭𝐲-\r\n1 Year Free Replacement & 5 Years Service Warranty','upload/products/thumbnail/1774741571693356.png','1 Gang Smart Switch(WI-Fi)- Stata IT Limited','Ultimate solution for seamless lighting control with our 1 gang smart switch(Wi-Fi) in Bangladesh. Effortlessly manage yo